#[repr(C,packed)]struct P{a:u8,b:u32}unsafe fn take<T>(p:*const T)->T{unsafe{core::ptr::read_unaligned(p)}}unsafe fn put<T>(p:*mut T,v:T){unsafe{core::ptr::write_unaligned(p,v)}}#[repr(C)]struct V{a:u32,b:u64}#[repr(C,packed)]struct Q{tag:u8,v:V}fn main(){let mut p=P{a:3,b:7};let r:unsafe fn(*const u32)->u32=core::ptr::read_unaligned::<u32>;let w:unsafe fn(*mut u32,u32)=core::ptr::write_unaligned::<u32>;unsafe{w(&raw mut p.b,r(&raw const p.b)+30);put(&raw mut p.b,take(&raw const p.b)+4);}check(p.a==3&&p.b==41);let mut q=Q{tag:3,v:V{a:7,b:37}};let r:unsafe fn(*const V)->V=core::ptr::read_unaligned::<V>;let w:unsafe fn(*mut V,V)=core::ptr::write_unaligned::<V>;unsafe{w(&raw mut q.v,r(&raw const q.v));put(&raw mut q.v,take(&raw const q.v));}check(q.v.a==7&&q.v.b==37);}
